#!/usr/bin/env python3

import json
import os
import select
import shutil
import signal
import sys
import termios
import tty
from dataclasses import dataclass
from typing import Any, Dict, Iterable, List, Optional, Tuple


HELP_TEXT = """  json-tui {OPTIONS} [file]

    A JSON terminal UI

  OPTIONS:

      file                              A JSON file. Omit to read from stdin.
      -h, --help                        Display this help menu.
      -v, --version                     Print version.
      -k, --key, --keybinding           Display key binding.
      -f, --fullscreen                  Display the JSON in fullscreen, in an
                                        alternate buffer
      "--" can be used to terminate flag options and force all following
      arguments to be treated as positional options

    If no file is given, json-tui reads JSON from the standard input
    Please report bugs to:https://github.com/ArthurSonzogni/json-tui/issues
"""

KEY_TEXT = (
    "┌───────────┬────────────────┐\r\n"
    "│\x1b[36m\x1b[49mkeys       \x1b[39m\x1b[49m│\x1b[36m\x1b[49maction          \x1b[39m\x1b[49m│\r\n"
    "├───────────┼────────────────┤\r\n"
    "│Navigate   │← ↑ ↓ →         │\r\n"
    "│           │h j k l         │\r\n"
    "│           │Mouse::WheelUp  │\r\n"
    "│           │Mouse::WheelDown│\r\n"
    "├───────────┼────────────────┤\r\n"
    "│Toggle     │enter           │\r\n"
    "│           │Mouse::Left     │\r\n"
    "├───────────┼────────────────┤\r\n"
    "│Deep       │                │\r\n"
    "│ - Expand  │+               │\r\n"
    "│ - Collapse│-               │\r\n"
    "├───────────┼────────────────┤\r\n"
    "│Exit       │Escape          │\r\n"
    "│           │q               │\r\n"
    "├───────────┼────────────────┤\r\n"
    "│Navigate   │                │\r\n"
    "│ - first   │page-up         │\r\n"
    "│ - last    │page-down       │\r\n"
    "│ - top     │gg              │\r\n"
    "│ - bottom  │G               │\r\n"
    "└───────────┴────────────────┘\x00\n"
)

VERSION_TEXT = "1.4.1\n"

ANSI_REVERSE = "\x1b[7m"
ANSI_REVERSE_OFF = "\x1b[27m"
ANSI_BOLD = "\x1b[1m"
ANSI_BOLD_OFF = "\x1b[22m"

FG_KEY = "\x1b[94m\x1b[49m"
FG_NUM = "\x1b[96m\x1b[49m"
FG_BOOL = "\x1b[93m\x1b[49m"
FG_STR = "\x1b[92m\x1b[49m"
FG_NULL = "\x1b[91m\x1b[49m"
FG_GRAY = "\x1b[90m\x1b[49m"
FG_HEADER = "\x1b[36m\x1b[49m"
FG_RESET = "\x1b[39m\x1b[49m"

Path = Tuple[Any, ...]
MISSING = object()


@dataclass(frozen=True)
class Focus:
    kind: str
    path: Path
    row: int = 0
    col: int = 0


@dataclass
class RenderLine:
    plain: str
    styled: str


def colorize(text: str, color: str) -> str:
    return f"{color}{text}{FG_RESET}"


def highlight(text: str, color: Optional[str] = None) -> str:
    if color:
        return f"{ANSI_REVERSE}{color}{text}{ANSI_REVERSE_OFF}{FG_RESET}"
    return f"{ANSI_REVERSE}{text}{ANSI_REVERSE_OFF}"


def emphasize(text: str) -> str:
    return f"{ANSI_BOLD}{text}{ANSI_BOLD_OFF}"


def key_literal(key: str) -> str:
    return json.dumps(key, ensure_ascii=False)


def json_literal(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"))


def sorted_object(pairs: Iterable[Tuple[str, Any]]) -> Dict[str, Any]:
    return {key: value for key, value in sorted(pairs, key=lambda item: item[0])}


def parse_json_text(text: str) -> Any:
    return json.loads(text, object_pairs_hook=sorted_object)


def format_parse_error(text: str, exc: json.JSONDecodeError) -> str:
    stripped = text.strip()
    if not stripped:
        return (
            "[json.exception.parse_error.101] parse error at line 1, column 1: "
            "attempting to parse an empty input; check that your input string or stream "
            "contains the expected JSON"
        )

    if exc.msg == "Expecting property name enclosed in double quotes":
        pos = max(0, exc.pos)
        last_read = text[max(0, pos - 1) : min(len(text), pos + 1)]
        last_read = last_read.replace("\n", "\\n").replace("\r", "\\r")
        return (
            f"[json.exception.parse_error.101] parse error at line {exc.lineno}, "
            f"column {exc.colno}: syntax error while parsing object key - invalid "
            f"literal; last read: '{last_read}'; expected string literal"
        )

    return (
        f"[json.exception.parse_error.101] parse error at line {exc.lineno}, "
        f"column {exc.colno}: {exc.msg}"
    )


def read_text_file(path: str) -> Optional[str]:
    try:
        with open(path, "r", encoding="utf-8") as handle:
            return handle.read()
    except OSError:
        return None


def is_container(value: Any) -> bool:
    return isinstance(value, (dict, list))


def terminal_size() -> os.terminal_size:
    return shutil.get_terminal_size((80, 24))


class Viewer:
    def __init__(self, data: Any, fullscreen: bool) -> None:
        self.data = data
        self.fullscreen = fullscreen
        self.tree_expanded: Dict[Path, bool] = {}
        self.cell_expanded: Dict[Path, bool] = {}
        self.table_path: Optional[Path] = None
        self.focus = Focus("tree", ())
        self.scroll_top = 0
        self.last_height = 0
        self.pending_g = False
        self.fd = sys.stdin.fileno()
        self.saved_termios: Optional[List[Any]] = None
        self.focus_line = 0

    def run(self) -> int:
        if os.isatty(self.fd):
            self._enter_raw_mode()
        try:
            self._write_startup()
            self._render()
            while True:
                key = self._read_key()
                if key is None:
                    continue
                if self._handle_key(key):
                    break
                self._render()
            return 0
        finally:
            self._write_shutdown()
            self._leave_raw_mode()

    def _enter_raw_mode(self) -> None:
        self.saved_termios = termios.tcgetattr(self.fd)
        attrs = termios.tcgetattr(self.fd)
        attrs[0] &= ~(termios.BRKINT | termios.ICRNL | termios.INPCK | termios.ISTRIP | termios.IXON)
        attrs[1] &= ~(termios.OPOST)
        attrs[2] |= termios.CS8
        attrs[3] &= ~(termios.ECHO | termios.ICANON | termios.IEXTEN | termios.ISIG)
        attrs[6][termios.VMIN] = 0
        attrs[6][termios.VTIME] = 1
        termios.tcsetattr(self.fd, termios.TCSAFLUSH, attrs)

    def _leave_raw_mode(self) -> None:
        if self.saved_termios is not None:
            termios.tcsetattr(self.fd, termios.TCSAFLUSH, self.saved_termios)
            self.saved_termios = None

    def _write_startup(self) -> None:
        out = ["\x00\x1bP$q q\x1b\\"]
        if self.fullscreen:
            out.append("\x1b[?1049h")
        out.append("\x1b[?7l\x1b[?1000h\x1b[?1003h\x1b[?1015h\x1b[?1006h")
        out.append("\x00\r\x1b[2K\x1b[?25l")
        sys.stdout.write("".join(out))
        sys.stdout.flush()

    def _write_shutdown(self) -> None:
        out = []
        if self.last_height > 1:
            out.append(f"\r\x1b[{self.last_height - 1}B")
        out.append("\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1000l\x1b[?7h")
        if self.fullscreen:
            out.append("\x1b[?1049l")
        out.append("\x1b[?25h\x1b[1 q\x00\r\n")
        sys.stdout.write("".join(out))
        sys.stdout.flush()

    def _read_key(self) -> Optional[str]:
        ready, _, _ = select.select([self.fd], [], [], 0.1)
        if not ready:
            return None
        data = os.read(self.fd, 1)
        if not data:
            return None

        if data == b"\x1b":
            extra = self._read_escape_tail()
            if not extra:
                return "escape"
            if extra == b"[A":
                return "up"
            if extra == b"[B":
                return "down"
            if extra == b"[C":
                return "right"
            if extra == b"[D":
                return "left"
            if extra == b"[5~":
                return "page-up"
            if extra == b"[6~":
                return "page-down"
            if extra.startswith(b"[<"):
                return self._parse_mouse(extra)

        return None

    if data == b"\r" or data == b"\n":
        return "enter"
    if data == b"q":
        return "quit"
    if data == b"j":
        return "down"
    if data == b"k":
        return "up"
    if data == b"h":
        return "left"
    if data == b"l":
        return "right"
    if data == b"+":
        return "expand-deep"
    if data == b"-":
        return "collapse-deep"
    if data == b"G":
        return "bottom"
    if data == b"g":
        return "g"
    return None

def _read_escape_tail(self) -> bytes:
    chunks = bytearray()
    deadline = os.times().elapsed + 0.05
    while os.times().elapsed < deadline:
        ready, _, _ = select.select([self.fd], [], [], max(0.0, deadline - os.times().elapsed))
        if not ready:
            break
        chunk = os.read(self.fd, 32)
        if not chunk:
            break
        chunks.extend(chunk)
        if chunks in (b"[A", b"[B", b"[C", b"[D", b"[5~", b"[6~"):
            break
        if chunks.startswith(b"[<") and (chunks.endswith(b"M") or chunks.endswith(b"m")):
            break
    return bytes(chunks)

def _parse_mouse(self, seq: bytes) -> Optional[str]:
    try:
        body = seq[2:-1].decode("ascii")
        button_text, _, _ = body.split(";")
        button = int(button_text)
    except (ValueError, UnicodeDecodeError):
        return None
    if button == 64:
        return "up"
    if button == 65:
        return "down"
    return None

def _handle_key(self, key: str) -> bool:
    if self.pending_g:
        self.pending_g = False
        if key == "g":
            self._jump_top()
            return False

    if key == "g":
        self.pending_g = True
        return False

    if key in ("quit", "escape"):
        return True

    if key == "page-up":
        self._jump_top()
        return False
    if key == "page-down":
        self._jump_bottom()
        return False
    if key == "bottom":
        self._jump_bottom()
        return False
    if key == "up":
        self._move_up()
        return False
    if key == "down":
        self._move_down()
        return False
    if key == "left":
        self._move_left()
        return False
    if key == "right":
        self._move_right()
        return False
    if key == "enter":
        self._toggle_current()
        return False
    if key == "expand-deep":
        self._deep_expand_current()
        return False
    if key == "collapse-deep":
        self._deep_collapse_current()
        return False
    return False

def _jump_top(self) -> None:
    if self.focus.kind in ("table_label", "table_cell"):
        self.focus = Focus("table_label", self.focus.path)
    else:
        self.focus = Focus("tree", ())

def _jump_bottom(self) -> None:
    if self.focus.kind in ("table_label", "table_cell"):
        if self.table_path is None:
            return
        rows = self._table_row_count(self.table_path)
        cols = self._table_col_count(self.table_path)
        if rows and cols:
            col = self.focus.col if self.focus.kind == "table_cell" else 0
            col = min(max(col, 0), cols - 1)
            self.focus = Focus("table_cell", self.table_path, rows - 1, col)
        return

    items = self._tree_visible_items()
    if items:
        self.focus = Focus("tree", items[-1])

def _move_up(self) -> None:
    if self.focus.kind == "table_label":
        return
    if self.focus.kind == "table_cell":
        if self.focus.row == 0:
            self.focus = Focus("table_label", self.focus.path)
        else:
            self.focus = Focus("table_cell", self.focus.path, self.focus.row - 1, self.focus.col)
        return

    items = self._tree_visible_items()
    if not items:
        return
    base_path = self.focus.path
    try:
        index = items.index(base_path)
    except ValueError:
        index = 0
    if index > 0:
        self.focus = Focus("tree", items[index - 1])

def _move_down(self) -> None:
    if self.focus.kind == "table_label":
        rows = self._table_row_count(self.focus.path)
        cols = self._table_col_count(self.focus.path)
        if rows and cols:
            self.focus = Focus("table_cell", self.focus.path, 0, 0)
        return
    if self.focus.kind == "table_cell":
        rows = self._table_row_count(self.focus.path)
        if self.focus.row + 1 < rows:
            self.focus = Focus("table_cell", self.focus.path, self.focus.row + 1, self.focus.col)
        return

    items = self._tree_visible_items()
    if not items:
        return
    base_path = self.focus.path
    try:
        index = items.index(base_path)
    except ValueError:
        index = -1
    if 0 <= index < len(items) - 1:
        self.focus = Focus("tree", items[index + 1])

def _move_left(self) -> None:
    if self.focus.kind == "tree_hint":
        self.focus = Focus("tree", self.focus.path)
        return
    if self.focus.kind == "table_cell" and self.focus.col > 0:
        self.focus = Focus("table_cell", self.focus.path, self.focus.row, self.focus.col - 1)

def _move_right(self) -> None:
    if self.focus.kind == "tree":
        value = self._get_value(self.focus.path)
        if (
            isinstance(value, list)
            and self._tree_is_expanded(self.focus.path, value)
            and self._supports_table(value)
        ):
            self.focus = Focus("tree_hint", self.focus.path)
        return
    if self.focus.kind == "table_cell":
        cols = self._table_col_count(self.focus.path)
        if self.focus.col + 1 < cols:
            self.focus = Focus("table_cell", self.focus.path, self.focus.row, self.focus.col + 1)

def _toggle_current(self) -> None:
    if self.focus.kind == "tree_hint":
        self.table_path = self.focus.path
        self.focus = Focus("table_label", self.focus.path)
        return

    if self.focus.kind == "table_label":
        self.table_path = None
        self.focus = Focus("tree_hint", self.focus.path)
        return

    if self.focus.kind == "table_cell":
        value = self._table_cell_value(self.focus.path, self.focus.row, self.focus.col)
        if is_container(value):
            cell_path = self._table_cell_path(self.focus.path, self.focus.row, self.focus.col)
            if cell_path is not None:
                current = self._cell_is_expanded(cell_path, cell_path, value)
                self.cell_expanded[cell_path] = not current
        return

    value = self._get_value(self.focus.path)
    if is_container(value):
        current = self._tree_is_expanded(self.focus.path, value)
        self.tree_expanded[self.focus.path] = not current

def _deep_expand_current(self) -> None:
    if self.focus.kind == "table_cell":
        value = self._table_cell_value(self.focus.path, self.focus.row, self.focus.col)
        if is_container(value):
            cell_path = self._table_cell_path(self.focus.path, self.focus.row, self.focus.col)
            if cell_path is not None:
                self._deep_expand_cells(cell_path)
        return
    if self.focus.kind == "table_label":
        return

    value = self._get_value(self.focus.path)
    if is_container(value):
        self._deep_expand_tree(self.focus.path)

def _deep_collapse_current(self) -> None:
    if self.focus.kind == "table_cell":
        value = self._table_cell_value(self.focus.path, self.focus.row, self.focus.col)
        if is_container(value):
            cell_path = self._table_cell_path(self.focus.path, self.focus.row, self.focus.col)
            if cell_path is not None:
                self._deep_collapse_cells(cell_path)
        return
    if self.focus.kind == "table_label":
        return

    value = self._get_value(self.focus.path)
    if is_container(value):
        self._deep_collapse_tree(self.focus.path)

def _tree_visible_items(self) -> List[Path]:
    items: List[Path] = []

    def walk(value: Any, path: Path) -> None:
        items.append(path)
        if path == self.table_path:
            return
        if not is_container(value):
            return
        if not self._tree_is_expanded(path, value):
            return
        if isinstance(value, dict):
            for key, child in value.items():
                walk(child, path + (key,))
        else:
            for index, child in enumerate(value):
                walk(child, path + (index,))

    walk(self.data, ())
    return items

def _table_row_count(self, array_path: Path) -> int:
    value = self._get_value(array_path)
    return len(value) if isinstance(value, list) else 0

def _table_columns(self, array_path: Path) -> List[str]:
    value = self._get_value(array_path)
    if not isinstance(value, list):
        return []
    keys = set()
    for row in value:
        if isinstance(row, dict):
            keys.update(row.keys())
    return sorted(keys)

def _table_col_count(self, array_path: Path) -> int:
    return len(self._table_columns(array_path))

def _table_cell_value(self, array_path: Path, row: int, col: int) -> Any:
    array_value = self._get_value(array_path)
    columns = self._table_columns(array_path)
    if not isinstance(array_value, list) or row < 0 or row >= len(array_value):
        return MISSING
    if col < 0 or col >= len(columns):
        return MISSING
    row_value = array_value[row]
    if not isinstance(row_value, dict):
        return MISSING
    return row_value.get(columns[col], MISSING)

def _table_cell_path(self, array_path: Path, row: int, col: int) -> Optional[Path]:
    columns = self._table_columns(array_path)
    if col < 0 or col >= len(columns):
        return None
    value = self._table_cell_value(array_path, row, col)
    if value is MISSING:

        return None
    return array_path + (row, columns[col])

def _tree_is_expanded(self, path: Path, value: Any) -> bool:
    if path in self.tree_expanded:
        return self.tree_expanded[path]
    depth = len(path)
    if depth == 0:
        return True
    return isinstance(value, dict) and depth == 1

def _cell_is_expanded(self, root_path: Path, path: Path, value: Any) -> bool:
    if path in self.cell_expanded:
        return self.cell_expanded[path]
    depth = len(path) - len(root_path)
    if depth == 0:
        return True
    return isinstance(value, dict) and depth == 1

def _deep_expand_tree(self, root_path: Path) -> None:
    nodes = self._container_nodes(root_path)
    collapsed = [(depth, path) for depth, path, value in nodes if not self._tree_is_expanded(path, value)]
    if not collapsed:
        return
    target_depth = min(depth for depth, _ in collapsed)
    for depth, path in collapsed:
        if depth == target_depth:
            self.tree_expanded[path] = True

def _deep_collapse_tree(self, root_path: Path) -> None:
    nodes = self._container_nodes(root_path)
    expanded = [(depth, path) for depth, path, value in nodes if self._tree_is_expanded(path, value)]
    if not expanded:
        return
    target_depth = max(depth for depth, _ in expanded)
    for depth, path in expanded:
        if depth == target_depth:
            self.tree_expanded[path] = False

def _deep_expand_cells(self, root_path: Path) -> None:
    nodes = self._container_nodes(root_path)
    collapsed = [
        (depth, path)
        for depth, path, value in nodes
        if not self._cell_is_expanded(root_path, path, value)
    ]
    if not collapsed:
        return
    target_depth = min(depth for depth, _ in collapsed)
    for depth, path in collapsed:
        if depth == target_depth:
            self.cell_expanded[path] = True

def _deep_collapse_cells(self, root_path: Path) -> None:
    nodes = self._container_nodes(root_path)
    expanded = [
        (depth, path)
        for depth, path, value in nodes
        if self._cell_is_expanded(root_path, path, value)
    ]
    if not expanded:
        return
    target_depth = max(depth for depth, _ in expanded)
    for depth, path in expanded:
        if depth == target_depth:
            self.cell_expanded[path] = False

def _container_nodes(self, root_path: Path) -> List[Tuple[int, Path, Any]]:
    root_value = self._get_value(root_path)
    nodes: List[Tuple[int, Path, Any]] = []

    def walk(value: Any, path: Path, depth: int) -> None:
        if not is_container(value):
            return
        nodes.append((depth, path, value))
        if isinstance(value, dict):
            for key, child in value.items():
                walk(child, path + (key,), depth + 1)
        else:
            for index, child in enumerate(value):
                walk(child, path + (index,), depth + 1)

    walk(root_value, root_path, 0)
    return nodes

def _get_value(self, path: Path) -> Any:
    value = self.data
    for part in path:
        value = value[part]
    return value

def _supports_table(self, value: Any) -> bool:
    return isinstance(value, list) and len(value) > 0 and all(isinstance(item, dict) for item in value)

def _render(self) -> None:
    self.focus_line = 0
    lines = self._render_tree_node(self.data, (), None, True, 0)
    rows = max(1, terminal_size().lines)
    self._update_scroll(rows, len(lines))
    visible = lines[self.scroll_top : self.scroll_top + rows]

    output = []
    if self.fullscreen:
        output.append("\x1b[H\x1b[J")
    else:
        if self.last_height > 1:
            output.append(f"\r\x1b[{self.last_height - 1}A")
        output.append("\x1b[J")

    for index, line in enumerate(visible):
        output.append(line.styled)
        if index != len(visible) - 1:
            output.append("\r\n")

    sys.stdout.write("".join(output))
    sys.stdout.flush()
    self.last_height = max(1, len(visible))

def _update_scroll(self, rows: int, total_lines: int) -> None:
    if self.focus_line < self.scroll_top:
        self.scroll_top = self.focus_line
    elif self.focus_line >= self.scroll_top + rows:
        self.scroll_top = self.focus_line - rows + 1
    max_scroll = max(0, total_lines - rows)
    self.scroll_top = max(0, min(self.scroll_top, max_scroll))

def _render_tree_node(
    self,
    value: Any,
    path: Path,
    key: Optional[str],
    is_last: bool,
    indent: int,
) -> List[RenderLine]:
    if path == self.table_path:
        return self._render_table(path, key, is_last, indent)

    if isinstance(value, dict):
        return self._render_tree_container(value, path, key, is_last, indent, "{", "}")
    if isinstance(value, list):
        return self._render_tree_container(value, path, key, is_last, indent, "[", "]")
    return [self._render_tree_primitive(value, path, key, is_last, indent)]

def _render_tree_container(
    self,
    value: Any,
    path: Path,
    key: Optional[str],
    is_last: bool,
    indent: int,
    open_token: str,
    close_token: str,
) -> List[RenderLine]:
    lines: List[RenderLine] = []
    selected_value = self.focus.kind == "tree" and self.focus.path == path
    selected_hint = self.focus.kind == "tree_hint" and self.focus.path == path
    key_prefix_plain, key_prefix_styled = self._key_prefix(key)
    prefix = " " * indent

    expanded = self._tree_is_expanded(path, value)
    comma = "" if is_last else ","

    if not expanded:
        token = ("{...}" if isinstance(value, dict) else "[...]") + comma
        styled_token = highlight(token) if selected_value else emphasize(token)
        plain = f"{prefix}{key_prefix_plain}{token}"
        styled = f"{prefix}{key_prefix_styled}{styled_token}"
        lines.append(RenderLine(plain, styled))
        if selected_value or selected_hint:
            self.focus_line = self.scroll_top + len(lines) - 1
        return lines

    hint_plain = ""
    hint_styled = ""
    if isinstance(value, list) and self._supports_table(value):
        hint_plain = "   (table view)"
        hint_styled = highlight(hint_plain, FG_GRAY) if selected_hint else colorize(hint_plain, FG_GRAY)

    open_styled = highlight(open_token) if selected_value else emphasize(open_token)
    plain = f"{prefix}{key_prefix_plain}{open_token}{hint_plain}"
    styled = f"{prefix}{key_prefix_styled}{open_styled}{hint_styled}"
    lines.append(RenderLine(plain, styled))
    if selected_value or selected_hint:
        self.focus_line = self.scroll_top + len(lines) - 1

    if isinstance(value, dict):
        items = list(value.items())
        for index, (child_key, child_value) in enumerate(items):
            child_lines = self._render_tree_node(
                child_value,
                path + (child_key,),
                child_key,
                index == len(items) - 1,
                indent + 2,
            )
            lines.extend(child_lines)
    else:
        for index, child_value in enumerate(value):
            child_lines = self._render_tree_node(
                child_value,
                path + (index,),
                None,
                index == len(value) - 1,
                indent + 2,
            )
            lines.extend(child_lines)

    closing = f"{prefix}{close_token}{comma}"
    lines.append(RenderLine(closing, closing))
    return lines

def _render_tree_primitive(
    self,
    value: Any,
    path: Path,
    key: Optional[str],
    is_last: bool,
    indent: int,
) -> RenderLine:
    prefix = " " * indent
    key_prefix_plain, key_prefix_styled = self._key_prefix(key)
    literal = json_literal(value)
    color = self._value_color(value)
    selected = self.focus.kind == "tree" and self.focus.path == path
    styled_literal = highlight(literal, color) if selected else colorize(literal, color)
    comma = "" if is_last else ","
    line = RenderLine(
        f"{prefix}{key_prefix_plain}{literal}{comma}",
        f"{prefix}{key_prefix_styled}{styled_literal}{comma}",
    )
    if selected:
        self.focus_line = self.scroll_top
    return line

def _render_table(
    self,
    array_path: Path,
    key: Optional[str],
    is_last: bool,
    indent: int,
) -> List[RenderLine]:
    array_value = self._get_value(array_path)
    if not isinstance(array_value, list):
        return []

    columns = self._table_columns(array_path)
    index_width = max(1, len(str(max(0, len(array_value) - 1))))
    prefix = " " * indent
    key_prefix_plain, key_prefix_styled = self._key_prefix(key)

    label_plain = f"{prefix}{key_prefix_plain}(array view)"
    label_styled = f"{prefix}{key_prefix_styled}"
    if self.focus.kind == "table_label" and self.focus.path == array_path:
        label_styled += highlight("(array view)", FG_GRAY)
    else:
        label_styled += colorize("(array view)", FG_GRAY)

    lines = [RenderLine(label_plain, label_styled)]
    if self.focus.kind == "table_label" and self.focus.path == array_path:
        self.focus_line = 0

    rendered_cells: List[List[List[RenderLine]]] = []
    col_widths = [len(name) for name in columns]

    for row_index in range(len(array_value)):
        row_cells: List[List[RenderLine]] = []
        for col_index, _ in enumerate(columns):
            cell_value = self._table_cell_value(array_path, row_index, col_index)
            selected = (
                self.focus.kind == "table_cell"
                and self.focus.path == array_path
                and self.focus.row == row_index
                and self.focus.col == col_index
            )
            if cell_value is MISSING:
                if selected:
                    row_cells.append([RenderLine("", highlight(" "))])
                else:
                    row_cells.append([RenderLine("", "")])
                continue

            cell_path = self._table_cell_path(array_path, row_index, col_index)
            assert cell_path is not None
            cell_lines = self._render_cell_node(cell_value, cell_path, cell_path, 0, None, True, selected)
            row_cells.append(cell_lines)
            for cell_line in cell_lines:
                col_widths[col_index] = max(col_widths[col_index], len(cell_line.plain))
        rendered_cells.append(row_cells)

    top = prefix + (" " * index_width) + "┏" + "┳".join("━" * width for width in col_widths) + "┓"
    header_cells = "┃".join(name.ljust(col_widths[index]) for index, name in enumerate(columns))
    header = prefix + (" " * index_width) + "┃" + header_cells + "┃"
    sep = prefix + (" " * index_width) + "┡" + "╇".join("━" * width for width in col_widths) + "┩"
    lines.extend([RenderLine(top, top), RenderLine(header, header), RenderLine(sep, sep)])

    for row_index, row_cells in enumerate(rendered_cells):
        height = max((len(cell) for cell in row_cells), default=1)
        row_start = len(lines)
        for line_index in range(height):
            idx_plain = str(row_index) if line_index == 0 else " " * len(str(row_index))
            idx_plain = idx_plain.rjust(index_width)
            idx_styled = colorize(idx_plain, FG_GRAY)
            parts_plain = []
            parts_styled = []
            for col_index, cell in enumerate(row_cells):
                if line_index < len(cell):
                    cell_line = cell[line_index]
                    plain = cell_line.plain.ljust(col_widths[col_index])
                    styled = cell_line.styled + (" " * (col_widths[col_index] - len(cell_line.plain)))
                else:
                    plain = " " * col_widths[col_index]
                    styled = plain
                parts_plain.append(plain)
                parts_styled.append(styled)
            row_plain = prefix + idx_plain + "│" + "│".join(parts_plain) + "│"
            row_styled = prefix + idx_styled + "│" + "│".join(parts_styled) + "│"
            lines.append(RenderLine(row_plain, row_styled))
        if self.focus.kind == "table_cell" and self.focus.path == array_path and self.focus.row == row_index:
            self.focus_line = row_start

    bottom = prefix + (" " * index_width) + "└" + "┴".join("─" * width for width in col_widths) + "┘"
    if not is_last:
        bottom += ","
    lines.append(RenderLine(bottom, bottom))
    return lines

def _render_cell_node(
    self,
    value: Any,
    root_path: Path,
    path: Path,
    indent: int,
    key: Optional[str],
    is_last: bool,
    selected_root: bool,
) -> List[RenderLine]:
    if isinstance(value, dict):
        return self._render_cell_container(value, root_path, path, indent, key, is_last, "{", "}", selected_root)
    if isinstance(value, list):
        return self._render_cell_container(value, root_path, path, indent, key, is_last, "[", "]", selected_root)

    prefix = " " * indent
    key_prefix_plain, key_prefix_styled = self._key_prefix(key)
    literal = json_literal(value)
    color = self._value_color(value)
    selected = selected_root and path == root_path
    styled_literal = highlight(literal, color) if selected else colorize(literal, color)
    comma = "" if is_last else ","
    return [RenderLine(f"{prefix}{key_prefix_plain}{literal}{comma}", f"{prefix}{key_prefix_styled}{styled_literal}{comma}")]

def _render_cell_container(
    self,
    value: Any,
    root_path: Path,
    path: Path,
    indent: int,
    key: Optional[str],
    is_last: bool,
    open_token: str,
    close_token: str,

        selected_root: bool,
    ) -> List[RenderLine]:
        prefix = " " * indent
        key_prefix_plain, key_prefix_styled = self._key_prefix(key)
        expanded = self._cell_is_expanded(root_path, path, value)
        comma = "" if is_last else ","
        selected = selected_root and path == root_path

        if not expanded:
            token = ("{...}" if isinstance(value, dict) else "[...]") + comma
            styled_token = highlight(token) if selected else emphasize(token)
            return [RenderLine(f"{prefix}{key_prefix_plain}{token}", f"{prefix}{key_prefix_styled}{styled_token}")]

        open_styled = highlight(open_token) if selected else emphasize(open_token)
        lines = [RenderLine(f"{prefix}{key_prefix_plain}{open_token}", f"{prefix}{key_prefix_styled}{open_styled}")]
        if isinstance(value, dict):
            items = list(value.items())
            for index, (child_key, child_value) in enumerate(items):
                lines.extend(
                    self._render_cell_node(
                        child_value,
                        root_path,
                        path + (child_key,),
                        indent + 2,
                        child_key,
                        index == len(items) - 1,
                        False,
                    )
                )
        else:
            for index, child_value in enumerate(value):
                lines.extend(
                    self._render_cell_node(
                        child_value,
                        root_path,
                        path + (index,),
                        indent + 2,
                        None,
                        index == len(value) - 1,
                        False,
                    )
                )
        lines.append(RenderLine(f"{prefix}{close_token}{comma}", f"{prefix}{close_token}{comma}"))
        return lines

    def _key_prefix(self, key: Optional[str]) -> Tuple[str, str]:
        if key is None:
            return "", ""
        literal = key_literal(key)
        plain = f"{literal}: "
        styled = f"{colorize(literal, FG_KEY)}: "
        return plain, styled

    def _value_color(self, value: Any) -> str:
        if value is None:
            return FG_NULL
        if isinstance(value, bool):
            return FG_BOOL
        if isinstance(value, str):
            return FG_STR
        return FG_NUM


@dataclass
class ParsedArgs:
    valid: bool
    action: str
    fullscreen: bool
    file_path: Optional[str]


def parse_args(argv: List[str]) -> ParsedArgs:
    show_help = False
    show_version = False
    show_keys = False
    fullscreen = False
    file_path: Optional[str] = None
    parsing_flags = True

    for arg in argv[1:]:
        if parsing_flags and arg == "--":
            parsing_flags = False
            continue

        if parsing_flags and arg.startswith("-") and arg != "-":
            if arg in ("-h", "--help"):
                show_help = True
            elif arg in ("-v", "--version"):
                show_version = True
            elif arg in ("-k", "--key", "--keybinding"):
                show_keys = True
            elif arg in ("-f", "--fullscreen"):
                fullscreen = True
            else:
                return ParsedArgs(False, "invalid", False, None)
            continue

        if file_path is not None:
            return ParsedArgs(False, "invalid", False, None)
        file_path = arg

    if show_help:
        return ParsedArgs(True, "help", fullscreen, file_path)
    if show_version:
        return ParsedArgs(True, "version", fullscreen, file_path)
    if show_keys:
        return ParsedArgs(True, "keys", fullscreen, file_path)
    return ParsedArgs(True, "run", fullscreen, file_path)


def main(argv: List[str]) -> int:
    parsed = parse_args(argv)
    if not parsed.valid:
        sys.stderr.write("Invalid arguments\n")
        return 1

    if parsed.action == "help":
        sys.stdout.write(HELP_TEXT)
        return 0
    if parsed.action == "version":
        sys.stdout.write(VERSION_TEXT)
        return 0
    if parsed.action == "keys":
        sys.stdout.write(KEY_TEXT)
        return 0

    if parsed.file_path is not None:
        text = read_text_file(parsed.file_path)
        if text is None:
            sys.stderr.write(f"Could not open file {parsed.file_path}\n")
            return 1
    else:
        sys.stdout.write("Reading from stdin...\n")
        sys.stdout.flush()
        text = sys.stdin.read()

    try:
        data = parse_json_text(text)
    except json.JSONDecodeError as exc:
        sys.stderr.write("\n" + format_parse_error(text, exc) + "\n")
        return 1

    signal.signal(signal.SIGPIPE, signal.SIG_DFL)
    viewer = Viewer(data, parsed.fullscreen)
    return viewer.run()


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))

