def raw(text: str) -> Segment:
    return Segment(text)


def style_segment(text: str, *, color: Optional[int] = None, bold: bool = False,
                  selected: bool = False) -> Segment:
    prefix = ""
    suffix = ""
    if selected:
        prefix += "\x1b[7m"
        suffix = "\x1b[27m" + suffix
    if bold:
        prefix += "\x1b[1m"
        suffix = "\x1b[22m" + suffix
    if color is not None:
        prefix += f"\x1b[{color}m\x1b[49m"
        suffix = COLOR_RESET + suffix
    return Segment(text, prefix, suffix)


def blue_key(text: str) -> Segment:
    return style_segment(text, color=94)


def gray_hint(text: str, selected: bool) -> Segment:
    return style_segment(text, color=90, selected=selected)


def token(text: str, selected: bool, bold_when_unselected: bool = True) -> Segment:
    return style_segment(text, selected=selected, bold=bold_when_unselected and not selected)


def value_segment(value: Any, text: str, selected: bool) -> Segment:
    color = value_color(value)
    return style_segment(text, color=color, selected=selected)


def value_color(value: Any) -> Optional[int]:
    if value is None:
        return 91
    if value is True or value is False:
        return 93
    if isinstance(value, str):
        return 92
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return 96
    return None


def write_stdout(data: str) -> None:
    sys.stdout.buffer.write(data.encode("utf-8", "surrogatepass"))
    sys.stdout.buffer.flush()


def write_stderr(data: str) -> None:
    sys.stderr.write(data)
    sys.stderr.flush()


def is_container(value: Any) -> bool:
    return isinstance(value, (dict, list))


def is_array_of_objects(value: Any) -> bool:
    return isinstance(value, list) and bool(value) and all(isinstance(item, dict) for item in value)


def json_text(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"))


def get_node(root: Any, path: Path) -> Any:
    node = root
    for part in path:
        node = node[part]
    return node


def iter_children(value: Any) -> Iterable[tuple[Any, Any]]:
    if isinstance(value, dict):
        for key in sorted(value.keys()):
            yield key, value[key]
    elif isinstance(value, list):
        for index, item in enumerate(value):
            yield index, item


def is_descendant(path: Path, ancestor: Path) -> bool:
    return len(path) > len(ancestor) and path[: len(ancestor)] == ancestor


def collapse_subtree(expanded: set[Path], path: Path) -> None:
    for item in list(expanded):
        if item == path or is_descendant(item, path):
            expanded.discard(item)


def parse_args(argv: list[str]) -> tuple[dict[str, bool], Optional[str], bool]:
    options = {
        "help": False,
        "version": False,
        "key": False,
        "fullscreen": False,
    }
    positional: list[str] = []
    parse_flags = True

    for arg in argv:
        if parse_flags and arg == "--":
            parse_flags = False
            continue
        if parse_flags and arg.startswith("-") and arg != "-":

        if parse_flags and arg.startswith("-") and arg != "-":
            if arg in ("-h", "--help"):
                options["help"] = True
            elif arg in ("-v", "--version"):
