            elif arg in ("-f", "--fullscreen"):
                options["fullscreen"] = True
            else:
                return options, None, False
            continue
        positional.append(arg)

    if options["help"] or options["version"] or options["key"]:
        return options, positional[0] if positional else None, True
    if len(positional) > 1:
        return options, None, False
    return options, positional[0] if positional else None, True


def parse_json_or_error(text: str) -> tuple[Optional[Any], Optional[str]]:
    try:
        return json.loads(text), None
    except json.JSONDecodeError as exc:
        stripped = text.strip()
        if not stripped:
            return None, (
                "[json.exception.parse_error.101] parse error at line 1, column 1: "
                "attempting to parse an empty input; check that your input string or stream "
                "contains the expected JSON"
            )
        if exc.pos >= len(text) and exc.msg == "Expecting value":
            return None, (
                f"[json.exception.parse_error.101] parse error at line {exc.lineno}, "
                f"column {exc.colno}: syntax error while parsing value - unexpected end "
                "of input; expected '[', '{', or a literal"
            )
        return None, (
            f"[json.exception.parse_error.101] parse error at line {exc.lineno}, "
            f"column {exc.colno}: {exc.msg}"
        )


class InputReader:
    def __init__(self, fd: int) -> None:
        self.fd = fd
        self.buffer = b""

    def read_key(self) -> Optional[str]:
        while True:
            token = self._parse_buffer()
            if token is not None:
                return token
            data = os.read(self.fd, 64)
            if not data:
                return None
            self.buffer += data

    def _parse_buffer(self) -> Optional[str]:
        if not self.buffer:
            return None

        first = self.buffer[0]
        if first == 3:
            self.buffer = self.buffer[1:]
            return "quit"
        if first not in (0x1B,):
            self.buffer = self.buffer[1:]
            if first in (10, 13):
                return "enter"
            if first == ord("q"):
                return "quit"
            if first == ord("j"):
                return "down"
            if first == ord("k"):
                return "up"
            if first == ord("h"):
                return "left"
            if first == ord("l"):
                return "right"
            if first == ord("+"):
                return "plus"
            if first == ord("-"):
                return "minus"
            if first == ord("G"):
                return "capital_g"
            if first == ord("g"):
                return "g"
            return "ignore"

        if self.buffer == b"\x1b":
            ready, _, _ = select.select([self.fd], [], [], 0.02)
            if ready:
                return None
            self.buffer = b""
            return "quit"

        known = {
            b"\x1b[A": "up",
            b"\x1b[B": "down",
            b"\x1b[C": "right",
            b"\x1b[D": "left",
            b"\x1b[5~": "pageup",
            b"\x1b[6~": "pagedown",
        }
        for seq, token in known.items():
            if self.buffer.startswith(seq):
                self.buffer = self.buffer[len(seq):]
                return token

        if self.buffer.startswith(b"\x1b[<"):
            for end in (b"M", b"m"):
                pos = self.buffer.find(end)
                if pos != -1:
                    self.buffer = self.buffer[pos + 1:]
                    return "ignore"
            return None

        if self.buffer.startswith(b"\x1b["):
            for index, byte in enumerate(self.buffer[2:], start=2):
                if 0x40 <= byte <= 0x7E:
                    self.buffer = self.buffer[index + 1:]
                    return "ignore"
            return None

        self.buffer = self.buffer[1:]
        return "ignore"


class TerminalMode:
    def __init__(self, fd: Optional[int]) -> None:
        self.fd = fd
        self.saved: Optional[list[Any]] = None

    def __enter__(self) -> "TerminalMode":
        if self.fd is not None and os.isatty(self.fd):
            self.saved = termios.tcgetattr(self.fd)
            raw = termios.tcgetattr(self.fd)
            raw[3] &= ~(termios.ECHO | termios.ICANON | termios.IEXTEN | termios.ISIG)
            raw[1] &= ~termios.OPOST
            raw[0] &= ~(termios.IXON | termios.ICRNL | termios.BRKINT | termios.INPCK | termios.ISTRIP)
            raw[2] |= termios.CS8
            raw[6][termios.VMIN] = 1
            raw[6][termios.VTIME] = 0
            termios.tcsetattr(self.fd, termios.TCSANOW, raw)
        return self

    def __exit__(self, exc_type, exc, tb) -> None:
        if self.fd is not None and self.saved is not None:
            termios.tcsetattr(self.fd, termios.TCSANOW, self.saved)


class App:
    def __init__(self, root: Any, *, fullscreen: bool, input_fd: Optional[int], output_fd: int) -> None:
        self.root = root
        self.fullscreen = fullscreen
        self.input_fd = input_fd
        self.output_fd = output_fd
        self.expanded: set[Path] = set()
        self.active_table_path: Optional[Path] = None
        self.tree_selection = TreeSelection(())
        self.table_selection: Optional[TableSelection] = None
        self.pending_g = False
        self.scroll_top = 0
        self.previous_lines = 0
        self.initialize_state()

    def initialize_state(self) -> None:
        if is_container(self.root):
            self.expanded.add(())
            for key, child in iter_children(self.root):
                if isinstance(child, dict):
                    self.expanded.add((key,))

    def term_size(self) -> tuple[int, int]:
        for fd in (self.output_fd, self.input_fd):
            if fd is not None and os.isatty(fd):
                try:
                    size = os.get_terminal_size(fd)
                    return size.columns, size.lines
                except OSError:
                    pass
        return 80, 24

    def startup(self) -> None:
        seq = "\0\x1bP$q q\x1b\\"
        if self.fullscreen:
            seq += "\x1b[?1049h"
        seq += "\x1b[?7l\x1b[?1000h\x1b[?1003h\x1b[?1015h\x1b[?1006h\0\r"
        write_stdout(seq)

    def shutdown(self) -> None:
        if self.previous_lines > 1:
            write_stdout(f"\x1b[{self.previous_lines - 1}B")
        write_stdout("\r")
        seq = "\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1000l\x1b[?7h"
        if self.fullscreen:
            seq += "\x1b[?1049l"
        seq += "\x1b[?25h\x1b[1 q\0"
        seq += "\r" if self.fullscreen else "\r\n"
        write_stdout(seq)

    def clear_table_if_hidden(self, path: Path) -> None:
        if self.active_table_path is not None and (
            self.active_table_path == path or is_descendant(self.active_table_path, path)
        ):
            self.active_table_path = None
            self.table_selection = None
            self.tree_selection = TreeSelection(path)

    def toggle_expand(self, path: Path) -> None:
        value = get_node(self.root, path)
        if not is_container(value):
            return
        if path in self.expanded:
            collapse_subtree(self.expanded, path)
            self.clear_table_if_hidden(path)
        else:
            collapse_subtree(self.expanded, path)
            self.expanded.add(path)

    def deep_expand(self, path: Path) -> None:
        value = get_node(self.root, path)
        if not is_container(value):
            return
        if path not in self.expanded:
            self.expanded.add(path)
            return

        frontier: list[Path] = []

        def visit(node_path: Path, node: Any) -> None:
            if not is_container(node):
                return
            if node_path != path and node_path not in self.expanded:
                frontier.append(node_path)
                return
            for child_key, child in iter_children(node):
                child_path = node_path + (child_key,)
                if is_container(child):
                    if child_path in self.expanded:
                        visit(child_path, child)
                    else:
                        frontier.append(child_path)

        visit(path, value)
        for item in frontier:
            self.expanded.add(item)

    def deep_collapse(self, path: Path) -> None:
        if path not in self.expanded:
            return
        descendants = [item for item in self.expanded if item != path and is_descendant(item, path)]
        if descendants:
            deepest = []
            for item in descendants:
                if not any(other != item and is_descendant(other, item) for other in descendants):
                    deepest.append(item)
            for item in deepest:
                collapse_subtree(self.expanded, item)
                self.clear_table_if_hidden(item)
            return
        collapse_subtree(self.expanded, path)
        self.clear_table_if_hidden(path)

    def tree_targets(self) -> list[Path]:
        targets: list[Path] = []

        def visit(path: Path, node: Any) -> None:
            targets.append(path)
            if self.active_table_path == path:
                return
            if path not in self.expanded:
                return
            for child_key, child in iter_children(node):
                visit(path + (child_key,), child)

        visit((), self.root)
        return targets

    def normalize_tree_selection(self) -> None:
        targets = self.tree_targets()
        if not targets:
            self.tree_selection = TreeSelection(())
            return
        if self.tree_selection.path not in targets:
            self.tree_selection = TreeSelection(targets[0])
            return
        if self.tree_selection.slot == "hint":
            value = get_node(self.root, self.tree_selection.path)
            if not is_array_of_objects(value):
                self.tree_selection = TreeSelection(self.tree_selection.path)

    def move_tree(self, delta: int) -> None:
        targets = self.tree_targets()
        if not targets:
            return
        try:
            current = targets.index(self.tree_selection.path)
        except ValueError:

        except ValueError:
            current = 0
        next_index = max(0, min(len(targets) - 1, current + delta))
        self.tree_selection = TreeSelection(targets[next_index])

    def tree_page_up(self) -> None:
        targets = self.tree_targets()
        if not targets:
            return
        index = 1 if len(targets) > 1 else 0
        self.tree_selection = TreeSelection(targets[index])

    def tree_page_down(self) -> None:
        targets = self.tree_targets()
        if targets:
            self.tree_selection = TreeSelection(targets[-1])

    def tree_top(self) -> None:
        targets = self.tree_targets()
        if targets:
            self.tree_selection = TreeSelection(targets[0])

    def tree_bottom(self) -> None:
        targets = self.tree_targets()
        if targets:
            self.tree_selection = TreeSelection(targets[-1])

    def enter_table(self, path: Path) -> None:
        self.active_table_path = path
        self.table_selection = TableSelection(path)

    def leave_table(self) -> None:
        if self.active_table_path is None:
            return
        path = self.active_table_path
        self.active_table_path = None
        self.table_selection = None
        self.tree_selection = TreeSelection(path, "hint")

    def table_columns(self, path: Path) -> list[str]:
        array = get_node(self.root, path)
        columns: set[str] = set()
        for row in array:
            columns.update(row.keys())
        return sorted(columns)

    def move_table_vertical(self, delta: int) -> None:
        if self.table_selection is None:
            return
        path = self.table_selection.path
        rows = len(get_node(self.root, path))
        columns = self.table_columns(path)
        if not columns:
            return
        if self.table_selection.row is None:
            if delta > 0 and rows:
                self.table_selection = TableSelection(path, 0, 0)
            return
        row = self.table_selection.row + delta
        if row < 0:
            self.table_selection = TableSelection(path)
        elif row >= rows:
            self.table_selection = TableSelection(path, rows - 1, self.table_selection.col)
        else:
            self.table_selection = TableSelection(path, row, self.table_selection.col)

    def move_table_horizontal(self, delta: int) -> None:
        if self.table_selection is None or self.table_selection.row is None:
            return
        columns = self.table_columns(self.table_selection.path)
        if not columns:
            return
        col = max(0, min(len(columns) - 1, self.table_selection.col + delta))
        self.table_selection = TableSelection(self.table_selection.path, self.table_selection.row, col)

    def table_page(self, last: bool) -> None:
        if self.table_selection is None or self.table_selection.row is None:
            return
        rows = len(get_node(self.root, self.table_selection.path))
        if rows == 0:
            return
        row = rows - 1 if last else 0
        self.table_selection = TableSelection(self.table_selection.path, row, self.table_selection.col)

    def handle_tree_key(self, key: str) -> bool:
        self.pending_g = False if key != "g" else self.pending_g
        path = self.tree_selection.path
        value = get_node(self.root, path)

        if key == "quit":
            return False
        if key == "down":
            self.move_tree(1)
        elif key == "up":
            self.move_tree(-1)
        elif key == "pageup":
            self.tree_page_up()
        elif key == "pagedown":
            self.tree_page_down()
        elif key == "capital_g":
            self.tree_top()
        elif key == "g":
            if self.pending_g:
                self.tree_bottom()
                self.pending_g = False
            else:
                self.pending_g = True
            return True
        elif key == "right":
            if self.tree_selection.slot == "main" and is_array_of_objects(value):
                self.tree_selection = TreeSelection(path, "hint")
        elif key == "left":
            if self.tree_selection.slot == "hint":
                self.tree_selection = TreeSelection(path)
        elif key == "enter":
            if self.tree_selection.slot == "hint":
                self.enter_table(path)
            elif is_container(value):
                self.toggle_expand(path)
        elif key == "plus":
            if is_container(value):
                self.deep_expand(path)
        elif key == "minus":
            if is_container(value):
                self.deep_collapse(path)
        self.pending_g = False
        self.normalize_tree_selection()
        return True

    def handle_table_key(self, key: str) -> bool:
        if self.table_selection is None:
            return True
        if key == "quit":
            return False
        if key == "enter" and self.table_selection.row is None:
            self.leave_table()
            return True
        if key == "down":
            self.move_table_vertical(1)
        elif key == "up":
            self.move_table_vertical(-1)
        elif key == "right":
            self.move_table_horizontal(1)
        elif key == "left":
            self.move_table_horizontal(-1)
        elif key == "pageup":
            self.table_page(False)
        elif key == "pagedown":
            self.table_page(True)
        return True

    def process_key(self, key: Optional[str]) -> bool:
        if key is None:
            return False
        if key == "ignore":
            return True
        if self.active_table_path is not None:
            return self.handle_table_key(key)
        return self.handle_tree_key(key)

    def render(self) -> None:
        width, height = self.term_size()
        all_lines, selected_index = self.build_lines(width)
        visible_rows = height if self.fullscreen else min(height, max(1, len(all_lines)))
        max_top = max(0, len(all_lines) - visible_rows)
        self.scroll_top = min(self.scroll_top, max_top)
        if selected_index < self.scroll_top:
            self.scroll_top = selected_index
        elif selected_index >= self.scroll_top + visible_rows:
            self.scroll_top = selected_index - visible_rows + 1

        view = all_lines[self.scroll_top : self.scroll_top + visible_rows]
        if self.fullscreen:
            while len(view) < visible_rows:
                view.append("")

        self.write_lines(view)

    def write_lines(self, lines: list[str]) -> None:
        total = max(self.previous_lines, len(lines))
        out: list[str] = []
        if self.previous_lines == 0:
            out.append("\x1b[2K")
        else:
            out.append("\r\x1b[2K")
        for index in range(total):
            if index > 0:
                out.append("\r\n\x1b[2K")
            if index < len(lines):
                out.append(lines[index])
        if total > 1:
            out.append(f"\x1b[{total - 1}A")
        out.append("\r\x1b[?25l")
        write_stdout("".join(out))
        self.previous_lines = len(lines)

    def build_lines(self, width: int) -> tuple[list[str], int]:
        render_lines: list[RenderLine] = []
        self.build_node_lines((), self.root, 0, None, True, render_lines)
        strings = [self.clip_and_pad(line.parts, width) for line in render_lines]
        selected_index = 0
        for index, line in enumerate(render_lines):
            if line.selected:
                selected_index = index
                break
        return strings, selected_index

    def build_node_lines(self, path: Path, node: Any, indent: int, key: Optional[str], is_last: bool,
                         out: list[RenderLine]) -> None:
        if self.active_table_path == path and is_array_of_objects(node):
            self.build_table_lines(path, node, indent, key, out)
            return

        if isinstance(node, dict):
            self.build_object_lines(path, node, indent, key, is_last, out)
            return
        if isinstance(node, list):
            self.build_array_lines(path, node, indent, key, is_last, out)
            return
        selected = self.active_table_path is None and self.tree_selection.path == path and self.tree_selection.slot == "main"
        parts = self.prefix_parts(indent, key)
        parts.append(value_segment(node, json_text(node) + ("" if is_last else ","), selected))
        out.append(RenderLine(parts, selected))

    def build_object_lines(self, path: Path, node: dict[str, Any], indent: int, key: Optional[str], is_last: bool,
                           out: list[RenderLine]) -> None:
        selected = self.active_table_path is None and self.tree_selection.path == path and self.tree_selection.slot == "main"
        collapsed = path not in self.expanded
        if collapsed:
            parts = self.prefix_parts(indent, key)
            parts.append(token("{...}" + ("" if is_last else ","), selected))
            out.append(RenderLine(parts, selected))
            return

        open_parts = self.prefix_parts(indent, key)
        open_parts.append(token("{", selected))
        out.append(RenderLine(open_parts, selected))

        items = list(iter_children(node))
        for index, (child_key, child) in enumerate(items):
            self.build_node_lines(path + (child_key,), child, indent + 1, child_key, index == len(items) - 1, out)

        close_parts = [raw("  " * indent), raw("}" + ("" if is_last else ","))]
        out.append(RenderLine(close_parts))

    def build_array_lines(self, path: Path, node: list[Any], indent: int, key: Optional[str], is_last: bool,
                          out: list[RenderLine]) -> None:
        selected_main = self.active_table_path is None and self.tree_selection.path == path and self.tree_selection.slot == "main"
        selected_hint = self.active_table_path is None and self.tree_selection.path == path and self.tree_selection.slot == "hint"
        collapsed = path not in self.expanded
        hint = is_array_of_objects(node)
        if collapsed:
            parts = self.prefix_parts(indent, key)
            parts.append(token("[...]" + ("" if is_last else ","), selected_main))
            if hint:
                parts.append(raw("   "))
                parts.append(gray_hint("(table view)", selected_hint))
            out.append(RenderLine(parts, selected_main or selected_hint))
            return

        open_parts = self.prefix_parts(indent, key)
        open_parts.append(token("[", selected_main))
        if hint:
            open_parts.append(raw("   "))
            open_parts.append(gray_hint("(table view)", selected_hint))
        out.append(RenderLine(open_parts, selected_main or selected_hint))

        for index, child in enumerate(node):
            self.build_node_lines(path + (index,), child, indent + 1, None, index == len(node) - 1, out)

        close_parts = [raw("  " * indent), raw("]" + ("" if is_last else ","))]
        out.append(RenderLine(close_parts))

    def build_table_lines(self, path: Path, node: list[Any], indent: int, key: Optional[str],
                          out: list[RenderLine]) -> None:
        selected_hint = self.table_selection is not None and self.table_selection.path == path and self.table_selection.row is None
        hint_parts = []
        if key is not None:
            hint_parts.extend(self.prefix_parts(indent, key))
        else:
            hint_parts.append(raw("  " * indent))
        hint_parts.append(gray_hint("(array view)", selected_hint))
        out.append(RenderLine(hint_parts, selected_hint))

        columns = self.table_columns(path)
        index_width = max(1, len(str(max(0, len(node) - 1))))
        widths = []
        for column in columns:
            cell_width = len(column)
            for row in node:
                text = self.table_cell_text(row.get(column))
                cell_width = max(cell_width, len(text))
            widths.append(cell_width)

        prefix = "  " * indent
        top = prefix + " " + "\u250f" + "\u2533".join("\u2501" * width for width in widths) + "\u2513 "
        if widths:
            top = prefix + " " + "\u250f" + ("\u2501" * index_width) + "\u2533" + "\u2533".join(
                "\u2501" * width for width in widths
            ) + "\u2513 "
        mid = prefix + " " + "\u2521" + ("\u2501" * index_width) + "\u2547" + "\u2547".join(
            "\u2501" * width for width in widths
        ) + "\u2529 "
        bot = prefix + " " + "\u2514" + ("\u2500" * index_width) + "\u2534" + "\u2534".join(
            "\u2500" * width for width in widths
        ) + "\u2518 "
        out.append(RenderLine([raw(top)]))

        header_parts: list[Segment] = [raw(prefix), style_segment(" " * index_width, color=90), raw("\u2503")]
        for index, column in enumerate(columns):
            header_parts.append(raw(column.ljust(widths[index])))
            header_parts.append(raw("\u2503"))
        header_parts.append(raw(" "))
        out.append(RenderLine(header_parts))
        out.append(RenderLine([raw(mid)]))

        for row_index, row in enumerate(node):
            parts: list[Segment] = [raw(prefix), style_segment(str(row_index).ljust(index_width), color=90), raw("\u2502")]
            for col_index, column in enumerate(columns):
                cell_text = self.table_cell_text(row.get(column)).ljust(widths[col_index])
                selected = (
                    self.table_selection is not None
                    and self.table_selection.path == path
                    and self.table_selection.row == row_index
                    and self.table_selection.col == col_index
                )
                parts.append(self.table_cell_segment(row.get(column), cell_text, selected))
                parts.append(raw("\u2502"))
            parts.append(raw(" "))
            out.append(RenderLine(parts, any(
                self.table_selection is not None
                and self.table_selection.path == path
                and self.table_selection.row == row_index
                and self.table_selection.col == col_index
                for col_index in range(len(columns))
            )))

        out.append(RenderLine([raw(bot)]))

    def table_cell_text(self, value: Any) -> str:
        if isinstance(value, dict):
            return "{...}"
        if isinstance(value, list):
            return "[...]"
        return json_text(value)

    def table_cell_segment(self, value: Any, text: str, selected: bool) -> Segment:
        if isinstance(value, dict) or isinstance(value, list):
            return token(text, selected)
        return value_segment(value, text, selected)

    def prefix_parts(self, indent: int, key: Optional[str]) -> list[Segment]:
        parts = [raw("  " * indent)]
        if key is not None:
            parts.append(blue_key(json.dumps(key, ensure_ascii=False)))
            parts.append(raw(": "))
        return parts

    def clip_and_pad(self, parts: list[Segment], width: int) -> str:
        visible = 0
        output: list[str] = []
        for part in parts:
            if visible >= width:
                break
            remaining = width - visible
            take = min(remaining, len(part.text))
            if take <= 0:
                continue
            text = part.text[:take]
            output.append(part.prefix + text + part.suffix)
            visible += len(text)
        if visible < width:
            output.append(" " * (width - visible))
        return "".join(output)

    def run(self) -> int:
        self.startup()
        self.render()

        if self.input_fd is None:
            try:
                while True:
                    time.sleep(3600)
            finally:
                self.shutdown()

        with TerminalMode(self.input_fd):
            reader = InputReader(self.input_fd)
            while True:
                key = reader.read_key()
                if not self.process_key(key):
                    break
                self.render()
        self.shutdown()
        return 0


def main(argv: list[str]) -> int:
    options, filename, valid = parse_args(argv)
    if not valid:
        write_stderr("Invalid arguments\n")

        write_stderr("Invalid arguments\n")
        return 1

    if options["help"]:
        write_stdout(HELP_TEXT)
        return 0
    if options["version"]:
        write_stdout(VERSION_TEXT)
        return 0
    if options["key"]:
        write_stdout(KEY_TEXT)
        return 0

    text: str
    if filename is not None:
        try:
            with open(filename, "r", encoding="utf-8") as handle:
                text = handle.read()
        except OSError:
            write_stderr(f"Could not open file {filename}\n")
            return 1
    else:
        write_stdout("Reading from stdin...")
        text = sys.stdin.read()

    root, error = parse_json_or_error(text)
    if error is not None:
        write_stderr("\n" + error + "\n")
        return 1

    input_fd: Optional[int] = None
    if os.isatty(sys.stdin.fileno()):
        input_fd = sys.stdin.fileno()
    else:
        try:
            input_fd = os.open("/dev/tty", os.O_RDONLY)
        except OSError:
            input_fd = None

    app = App(root, fullscreen=options["fullscreen"], input_fd=input_fd, output_fd=sys.stdout.fileno())
    try:
        return app.run()
    finally:
        if input_fd is not None and input_fd != sys.stdin.fileno():
            os.close(input_fd)


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))

