func main() {
	code, err := realMain()
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	os.Exit(code)
}

func realMain() (int, error) {
	opts, err := parseOptions(os.Args[1:])
	if err != nil {
		return 1, err
	}

	switch opts.action {
	case actionHelp:
		fmt.Print(helpText)
		return 0, nil
	case actionVersion:
		fmt.Println(version)
		return 0, nil
	case actionKeybinding:
		fmt.Print(keybindingText)
		return 0, nil
	}

	input, err := readInput(opts.file)
	if err != nil {
		return 1, err
	}

	root, err := parseJSON(input)
	if err != nil {
		return 1, err
	}

	app := newApp(root, opts.fullscreen)
	term, err := newTerminal(opts.fullscreen)
	if err != nil {
		return 1, err
	}
	defer term.leave()

	for {
		if err := term.render(app); err != nil {
			return 1, err
		}
		ev, err := term.nextEvent()
		if err != nil {
			return 1, err
		}
		if handleEvent(app, term, ev) {
			return 0, nil
		}
	}
}

func parseOptions(args []string) (options, error) {
	var opts options
	var positional []string
	parseFlags := true

	for _, arg := range args {
		if parseFlags && arg == "--" {
			parseFlags = false
			continue
		}
		if parseFlags && strings.HasPrefix(arg, "-") && arg != "-" {
			switch arg {
			case "-h", "--help":
				opts.action = actionHelp
			case "-v", "--version":
				opts.action = actionVersion
			case "-k", "-key", "--key", "-keybinding", "--keybinding":
				opts.action = actionKeybinding
			case "-f", "--fullscreen":

				opts.fullscreen = true
			default:
				return options{}, errors.New("Invalid arguments")
			}
			continue
		}
		positional = append(positional, arg)
	}

	if len(positional) > 1 {
		return options{}, errors.New("Invalid arguments")
	}
	if len(positional) == 1 {
		opts.file = positional[0]
	}
	return opts, nil
}

func readInput(file string) (string, error) {
	if file != "" {
		data, err := os.ReadFile(file)
		if err != nil {
			return "", fmt.Errorf("Could not open file %s", file)
		}
		return string(data), nil
	}
	fmt.Fprintln(os.Stderr, "Reading from stdin...")
	data, err := io.ReadAll(os.Stdin)
	if err != nil {
		return "", err
	}
	return string(data), nil
}

func parseJSON(input string) (any, error) {
	if strings.TrimSpace(input) == "" {
		return nil, errors.New("[json.exception.parse_error.101] parse error at line 1, column 1: attempting to parse an empty input; check that your input string or stream contains the expected JSON")
	}
	dec := json.NewDecoder(strings.NewReader(input))
	dec.UseNumber()
	var root any
	if err := dec.Decode(&root); err != nil {
		line, col := lineColForOffset(input, syntaxErrorOffset(err))
		if line == 0 {
			line, col = 1, 1
		}
		return nil, fmt.Errorf("[json.exception.parse_error.101] parse error at line %d, column %d: %s", line, col, err.Error())
	}
	return root, nil
}

func syntaxErrorOffset(err error) int {
	var syntaxErr *json.SyntaxError
	if errors.As(err, &syntaxErr) {
		return int(syntaxErr.Offset)
	}
	var typeErr *json.UnmarshalTypeError
	if errors.As(err, &typeErr) {
		return int(typeErr.Offset)
	}
	return 0
}

func lineColForOffset(input string, offset int) (int, int) {
	if offset <= 0 {
		return 0, 0
	}
	line, col := 1, 1
	for i, r := range input {
		if i+1 >= offset {
			break
		}
		if r == '\n' {
			line++
			col = 1
		} else {
			col++
		}
	}
	return line, col
}

func newApp(root any, fullscreen bool) *app {
	expanded := map[string]bool{}
	collectDefaultExpansions(root, nil, expanded)
	return &app{
		root:          root,
		fullscreen:    fullscreen,
		expanded:      expanded,
		tableMode:     map[string]bool{},
		expandedCells: map[string]bool{},
		focus: focus{
			kind: focusTree,
			path: nil,
		},
	}
}

func collectDefaultExpansions(node any, p path, expanded map[string]bool) {
	shouldExpand := len(p) == 0 || (len(p) == 1 && isObject(node))
	if !shouldExpand {
		return
	}
	expanded[pathID(p)] = true
	switch v := node.(type) {
	case []any:
		for i, child := range v {
			collectDefaultExpansions(child, appendPathIndex(p, i), expanded)
		}
	case map[string]any:
		for _, key := range sortedKeys(v) {
			collectDefaultExpansions(v[key], appendPathKey(p, key), expanded)
		}
	}
}

func handleEvent(app *app, term *terminal, ev inputEvent) bool {
	switch ev.kind {
	case eventEscape:
		return true
	case eventRune:
		switch ev.r {
		case 'q':
			return true
		case 'j':
			app.moveVertical(term.width, 1)
		case 'k':
			app.moveVertical(term.width, -1)
		case 'h':
			app.moveHorizontal(-1)
		case 'l':
			app.moveHorizontal(1)
		case '+':
			app.deepExpand()
		case '-':
			app.deepCollapse()
		case 'g':
			if app.pendingG {
				app.pendingG = false
				app.jumpTop(term.width)
			} else {
				app.pendingG = true
			}
		case 'G':
			app.pendingG = false
			app.jumpBottom(term.width)
		}
	case eventUp:
		app.pendingG = false
		app.moveVertical(term.width, -1)
	case eventDown:
		app.pendingG = false
		app.moveVertical(term.width, 1)
	case eventLeft:
		app.pendingG = false
		app.moveHorizontal(-1)
	case eventRight:
		app.pendingG = false
		app.moveHorizontal(1)
	case eventPageUp:
		app.pendingG = false
		app.pageMove(term.width, -term.viewportHeight())
	case eventPageDown:
		app.pendingG = false
		app.pageMove(term.width, term.viewportHeight())
	case eventEnter:
		app.pendingG = false
		app.activate()
	case eventWheelUp:
		app.pendingG = false
		app.moveVertical(term.width, -1)
	case eventWheelDown:
		app.pendingG = false
		app.moveVertical(term.width, 1)
	case eventLeftClick:
		app.pendingG = false
		app.handleClick(term, ev.x, ev.y)
	}
	return false
}

func newTerminal(fullscreen bool) (*terminal, error) {
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return nil, err
	}
	fd := int(tty.Fd())
	oldState, err := makeRaw(fd)
	if err != nil {
		tty.Close()
		return nil, err
	}

	term := &terminal{
		tty:        tty,
		fd:         fd,
		oldState:   oldState,
		fullscreen: fullscreen,
	}
	term.refreshSize()
	if fullscreen {
		term.startRow = 0
	} else {
		row, _ := queryCursorPosition(fd, tty)
		term.startRow = row
	}

	var b strings.Builder
	b.WriteString("\x1bP$q q\x1b\\")
	if fullscreen {
		b.WriteString("\x1b[?1049h")
	}
	b.WriteString("\x1b[?7l")
	b.WriteString("\x1b[?1000h\x1b[?1003h\x1b[?1015h\x1b[?1006h")
	b.WriteString("\x1b[?25l")
	if _, err := io.WriteString(tty, b.String()); err != nil {
		tty.Close()
		return nil, err
	}
	return term, nil
}

func (t *terminal) leave() {
	if t.tty == nil {
		return
	}
	var b strings.Builder
	b.WriteString("\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1000l")
	b.WriteString("\x1b[?7h")
	b.WriteString("\x1b[?25h")
	if t.fullscreen {
		b.WriteString("\x1b[?1049l")
	} else {
		row := t.startRow + t.lastDrawn
		b.WriteString(cursorMove(row, 0))
		b.WriteString("\r\n")
	}
	b.WriteString("\x1b[1 q")
	io.WriteString(t.tty, b.String())
	restoreTermios(t.fd, t.oldState)
	t.tty.Close()
	t.tty = nil
}

func (t *terminal) refreshSize() {
	type winsize struct {
		row    uint16
		col    uint16
		xpixel uint16
		ypixel uint16
	}
	ws := winsize{}
	_, _, _ = syscall.Syscall(syscall.SYS_IOCTL, uintptr(t.fd), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	if ws.col == 0 || ws.row == 0 {
		t.width, t.height = 80, 24
		return
	}
	t.width, t.height = int(ws.col), int(ws.row)
}

func (t *terminal) viewportHeight() int {
	t.refreshSize()
	if t.fullscreen {
		return max(1, t.height)
	}
	return max(1, t.height-t.startRow)
}

func (t *terminal) render(app *app) error {
	t.refreshSize()
	render := app.buildRender(t.width)
	app.clampFocus(render)
	app.adjustScroll(render, t.viewportHeight())

	drawCount := min(len(render.lines)-app.scroll, t.viewportHeight())
	if drawCount < 0 {
		drawCount = 0
	}
	clearCount := max(drawCount, t.lastDrawn)

	var b strings.Builder
	for row := 0; row < clearCount; row++ {
		b.WriteString(cursorMove(t.startRow+row, 0))
		b.WriteString("\x1b[2K")
		if row < drawCount {
			b.WriteString(renderANSI(render.lines[app.scroll+row], t.width))
		}
	}
	if t.fullscreen {
		for row := clearCount; row < t.viewportHeight(); row++ {
			b.WriteString(cursorMove(t.startRow+row, 0))
			b.WriteString("\x1b[2K")
		}
	}
	if _, err := io.WriteString(t.tty, b.String()); err != nil {
		return err
	}
	t.lastDrawn = drawCount
	return nil
}

func (t *terminal) nextEvent() (inputEvent, error) {
	for {
		if ev, n, ok := parseInputEvent(t.inputBuffer); ok {
			t.inputBuffer = t.inputBuffer[n:]
			return ev, nil
		}
		if len(t.inputBuffer) == 1 && t.inputBuffer[0] == 0x1b && !waitReadable(t.fd, 30) {
			t.inputBuffer = t.inputBuffer[1:]
			return inputEvent{kind: eventEscape}, nil
		}
		buf := make([]byte, 64)
		n, err := syscall.Read(t.fd, buf)
		if err == syscall.EINTR {
			continue
		}
		if err != nil {
			return inputEvent{}, err
		}
		if n == 0 {
			continue
		}
		t.inputBuffer = append(t.inputBuffer, buf[:n]...)
	}
}

