func queryCursorPosition(fd int, tty *os.File) (int, int) {
	io.WriteString(tty, "\x1b[6n")
	var buf []byte
	for i := 0; i < 8; i++ {
		if !waitReadable(fd, 50) {
			break
		}
		tmp := make([]byte, 32)
		n, err := syscall.Read(fd, tmp)
		if err != nil || n <= 0 {
			break
		}
		buf = append(buf, tmp[:n]...)
		if bytes.Contains(buf, []byte{'R'}) {
			break
		}
	}
	if len(buf) == 0 {
		return 0, 0
	}
	if len(buf) > 0 && buf[0] == 0x1b && len(buf) > 2 && buf[1] == '[' {
		body := string(buf[2:])
		if idx := strings.IndexByte(body, 'R'); idx >= 0 {
			parts := strings.Split(body[:idx], ";")
			if len(parts) == 2 {
				row, _ := strconv.Atoi(parts[0])
				col, _ := strconv.Atoi(parts[1])
				return max(0, row-1), max(0, col-1)
			}
		}
	}
	return 0, 0
}

func waitReadable(fd int, timeoutMs int) bool {
	var readfds syscall.FdSet
	readfds.Bits[fd/64] |= 1 << (uint(fd) % 64)
	tv := syscall.Timeval{
		Sec:  int64(timeoutMs / 1000),
		Usec: int64(timeoutMs%1000) * 1000,
	}
	n, err := syscall.Select(fd+1, &readfds, nil, nil, &tv)
	return err == nil && n > 0
}

func makeRaw(fd int) (syscall.Termios, error) {
	var oldState syscall.Termios
	if _, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&oldState))); errno != 0 {
		return syscall.Termios{}, errno
	}
	raw := oldState
	raw.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	raw.Oflag &^= syscall.OPOST
	raw.Lflag &^= syscall.ECHO | syscall.ICANON | syscall.IEXTEN
	raw.Cflag &^= syscall.CSIZE | syscall.PARENB
	raw.Cflag |= syscall.CS8
	raw.Cc[syscall.VMIN] = 0
	raw.Cc[syscall.VTIME] = 1
	if _, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(&raw))); errno != 0 {
		return syscall.Termios{}, errno
	}
	return oldState, nil
}

func restoreTermios(fd int, state syscall.Termios) {
	syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(&state)))
}

func cursorMove(row, col int) string {
	return fmt.Sprintf("\x1b[%d;%dH", row+1, col+1)
}

func renderANSI(line styledLine, width int) string {
	var b strings.Builder
	current := face{}
	used := 0
	for _, seg := range line.segments {
		if used >= width {
			break
		}
		text := clipToWidth(seg.text, width-used)
		if text == "" {
			continue
		}
		if seg.face != current {
			b.WriteString(faceANSI(seg.face))
			current = seg.face
		}
		b.WriteString(text)
		used += stringWidth(text)
	}
	if current != (face{}) {
		b.WriteString("\x1b[39;22;27m")
	}
	return b.String()
}

func faceANSI(f face) string {
	codes := []string{"39", "22", "27"}
	if f.fg != "" {
		codes[0] = f.fg
	}
	if f.bold {
		codes[1] = "1"
	}
	if f.reverse {
		codes[2] = "7"
	}
	return "\x1b[" + strings.Join(codes, ";") + "m"
}

func (app *app) buildRender(width int) renderOutput {
	var out renderOutput
	app.renderTreeNode(&out, app.root, nil, 0, "", false, true, width)
	return out
}

func (app *app) renderTreeNode(out *renderOutput, node any, p path, depth int, key string, hasKey, isLast bool, width int) {
	if app.tableMode[pathID(p)] && isTableCandidate(node) {
		app.renderTableView(out, node, p, depth, key, hasKey, isLast, width)
		return
	}

	startLine := len(out.lines)
	itemIndex := len(out.items)
	out.items = append(out.items, verticalItem{
		kind:      verticalTree,
		path:      clonePath(p),
		startLine: startLine,
		endLine:   startLine,
	})
	switch v := node.(type) {
	case nil, bool, string, json.Number, float64:
		app.renderPrimitive(out, node, p, depth, key, hasKey, isLast, width)
	case []any:
		app.renderContainer(out, node, p, depth, key, hasKey, isLast, width, "[", "]", v)
	case map[string]any:
		app.renderContainer(out, node, p, depth, key, hasKey, isLast, width, "{", "}", v)
	}
	endLine := len(out.lines) - 1
	if endLine < startLine {
		endLine = startLine
	}
	out.items[itemIndex].endLine = endLine
}

func (app *app) renderPrimitive(out *renderOutput, node any, p path, depth int, key string, hasKey, isLast bool, width int) {
	value := serializeValue(node)
	pfx := linePrefix(depth, key, hasKey)
	cont := continuationPrefix(depth, key, hasKey)
	firstWidth := max(1, width-pfx.width)
	contWidth := max(1, width-cont.width)
	chunks := wrapText(value, firstWidth, contWidth)
	selected := app.focus.kind == focusTree && pathsEqual(app.focus.path, p) && !app.focus.toggle
	for i, chunk := range chunks {
		var line styledLine
		if i == 0 {
			pushPrefix(&line, pfx)
		} else {
			pushPrefix(&line, cont)
		}
		if i == 0 && !isLast {
			chunk += ","
		}
		line.push(chunk, primitiveFace(node).withReverse(selected && i == 0))
		out.lines = append(out.lines, line)
	}
}

func (app *app) renderContainer(out *renderOutput, node any, p path, depth int, key string, hasKey, isLast bool, width int, open, close string, value any) {
	var line styledLine
	pushPrefix(&line, linePrefix(depth, key, hasKey))
	selectedPrimary := app.focus.kind == focusTree && pathsEqual(app.focus.path, p) && !app.focus.toggle
	selectedToggle := app.focus.kind == focusTree && pathsEqual(app.focus.path, p) && app.focus.toggle
	expanded := app.expanded[pathID(p)]
	if expanded {
		line.push(open, face{bold: true, reverse: selectedPrimary})
	} else {
		marker := collapsedMarker(node)
		if !isLast {
			marker += ","
		}
		line.push(marker, face{bold: true, reverse: selectedPrimary})
	}
	if isTableCandidate(node) {
		line.push("   ", face{})
		line.push("(table view)", face{fg: fgHint, reverse: selectedToggle})
	}
	out.lines = append(out.lines, line)
	if !expanded {
		return
	}
	switch v := value.(type) {
	case []any:
		for i, child := range v {
			app.renderTreeNode(out, child, appendPathIndex(p, i), depth+1, "", false, i == len(v)-1, width)
		}
	case map[string]any:
		keys := sortedKeys(v)
		for i, childKey := range keys {
			app.renderTreeNode(out, v[childKey], appendPathKey(p, childKey), depth+1, childKey, true, i == len(keys)-1, width)
		}
	}
	var closing styledLine
	closing.push(strings.Repeat(" ", depth*2), face{})
	text := close
	if !isLast {
		text += ","
	}
	closing.push(text, face{})
	out.lines = append(out.lines, closing)
}

func (app *app) renderTableView(out *renderOutput, node any, p path, depth int, key string, hasKey, isLast bool, width int) {
	toggleLine := len(out.lines)
	var line styledLine
	pushPrefix(&line, linePrefix(depth, key, hasKey))
	line.push("(array view)", face{fg: fgHint, reverse: app.focus.kind == focusTableToggle && pathsEqual(app.focus.path, p)})
	out.lines = append(out.lines, line)
	out.items = append(out.items, verticalItem{
		kind:      verticalTableToggle,
		path:      clonePath(p),
		startLine: toggleLine,
		endLine:   toggleLine,
	})

	rows, _ := node.([]any)
	columns := tableColumns(node)
	if len(columns) == 0 {
		return
	}

	type blockRow [][]styledLine
	var blocks []blockRow
	colWidths := make([]int, len(columns))
	for i, name := range columns {
		colWidths[i] = stringWidth(name)
	}
	for rowIndex, row := range rows {
		obj, ok := row.(map[string]any)
		if !ok {
			continue
		}
		rowBlocks := make([][]styledLine, len(columns))
		for colIndex, column := range columns {
			block := app.renderTableCellBlock(p, rowIndex, column, obj[column], width)
			rowBlocks[colIndex] = block
			colWidths[colIndex] = max(colWidths[colIndex], blockMaxWidth(block))
		}
		blocks = append(blocks, rowBlocks)
	}

	indexWidth := len(strconv.Itoa(max(0, len(rows)-1)))
	if indexWidth < 1 {
		indexWidth = 1
	}
	out.lines = append(out.lines, tableBorderLine(depth*2+indexWidth, colWidths, "┏", "┳", "┓"))
	out.lines = append(out.lines, tableHeaderLine(depth*2, indexWidth, columns, colWidths))
	out.lines = append(out.lines, tableBorderLine(depth*2+indexWidth, colWidths, "┡", "╇", "┩"))

	for rowIndex, rowBlocks := range blocks {
		start := len(out.lines)
		rowHeight := 1
		for _, block := range rowBlocks {
			rowHeight = max(rowHeight, len(block))
		}
		for subline := 0; subline < rowHeight; subline++ {
			var line styledLine
			line.push(strings.Repeat(" ", depth*2), face{})
			indexText := strings.Repeat(" ", indexWidth)
			if subline == 0 {
				indexText = fmt.Sprintf("%*d", indexWidth, rowIndex)
			}
			line.push(indexText, face{fg: fgHint})
			line.push("│", face{})
			for colIndex, block := range rowBlocks {
				var cellLine styledLine
				if subline < len(block) {
					cellLine = block[subline]
				}
				selected := app.focus.kind == focusTableCell &&
					pathsEqual(app.focus.path, p) &&
					app.focus.row == rowIndex &&
					app.focus.column == colIndex
				appendStyledLine(&line, cellLine, selected && subline == 0)
				fill := colWidths[colIndex] - cellLine.width
				if fill > 0 {
					line.push(strings.Repeat(" ", fill), face{})
				}
				line.push("│", face{})
			}
			out.lines = append(out.lines, line)
		}
		out.items = append(out.items, verticalItem{
			kind:        verticalTableRow,
			path:        clonePath(p),
			row:         rowIndex,
			startLine:   start,
			endLine:     len(out.lines) - 1,
			columnCount: len(columns),
		})
	}
	bottom := tableBorderLine(depth*2+indexWidth, colWidths, "└", "┴", "┘")
	if !isLast {
		bottom.push(",", face{})
	}
	out.lines = append(out.lines, bottom)
}

func (app *app) renderTableCellBlock(arrayPath path, row int, column string, value any, width int) []styledLine {
	if value == nil {
		return []styledLine{{}}
	}
	ref := cellRef{arrayPath: clonePath(arrayPath), row: row, column: column}
	return app.renderEmbeddedValue(value, ref, width)
}

func (app *app) renderEmbeddedValue(node any, ref cellRef, width int) []styledLine {
	cellExpanded := app.expandedCells[cellID(ref)]
	if len(ref.innerPath) == 1 && isObject(node) {
		cellExpanded = cellExpanded || true
	}
	switch v := node.(type) {
	case nil, bool, string, json.Number, float64:
		var line styledLine
		line.push(serializeValue(v), primitiveFace(v))
		return []styledLine{line}
	case []any:
		if !cellExpanded {
			var line styledLine
			line.push("[...]", face{bold: true})
			return []styledLine{line}
		}
		lines := []styledLine{{}}
		lines[0].push("[", face{bold: true})
		for i, child := range v {
			childRef := ref
			childRef.innerPath = appendPathIndex(ref.innerPath, i)
			childLines := app.renderEmbeddedValue(child, childRef, max(1, width-2))
			for j, childLine := range childLines {
				var line styledLine
				line.push("  ", face{})
				appendStyledLine(&line, childLine, false)
				if j == 0 && i != len(v)-1 {
					line.push(",", face{})
				}
				lines = append(lines, line)
			}
		}
		var closing styledLine
		closing.push("]", face{})
		lines = append(lines, closing)
		return lines
	case map[string]any:
		if !cellExpanded {
			var line styledLine
			line.push("{...}", face{bold: true})
			return []styledLine{line}
		}
		lines := []styledLine{{}}
		lines[0].push("{", face{bold: true})
		keys := sortedKeys(v)
		for i, key := range keys {
			childRef := ref
			childRef.innerPath = appendPathKey(ref.innerPath, key)
			childLines := app.renderEmbeddedValue(v[key], childRef, max(1, width-2))
			pfx := linePrefix(1, key, true)
			for j, childLine := range childLines {
				var line styledLine
				if j == 0 {
					pushPrefix(&line, pfx)
				} else {
					line.push("  ", face{})
				}
				appendStyledLine(&line, childLine, false)
				if j == 0 && i != len(keys)-1 {
					line.push(",", face{})
				}
				lines = append(lines, line)
			}
		}
		var closing styledLine

		var closing styledLine
		closing.push("}", face{})
		lines = append(lines, closing)
		return lines
	default:
		var line styledLine
		line.push(serializeValue(v), face{})
		return []styledLine{line}
	}
}

func (app *app) moveVertical(width, delta int) {
	render := app.buildRender(width)
	if len(render.items) == 0 {
		return
	}
	index := selectedVerticalIndex(render, app.focus)
	next := clamp(index+delta, 0, len(render.items)-1)
	app.focus = focusForItem(render.items[next], app.focus)
}

func (app *app) pageMove(width, delta int) {
	app.moveVertical(width, delta)
}

func (app *app) moveHorizontal(delta int) {
	switch app.focus.kind {
	case focusTree:
		if app.focus.toggle {
			if delta < 0 {
				app.focus.toggle = false
			}
			return
		}
		if delta > 0 {
			node, ok := getNode(app.root, app.focus.path)
			if ok && isTableCandidate(node) && !app.tableMode[pathID(app.focus.path)] {
				app.focus.toggle = true
			}
		}
	case focusTableCell:
		node, ok := getNode(app.root, app.focus.path)
		if !ok {
			return
		}
		columns := tableColumns(node)
		if len(columns) == 0 {
			return
		}
		app.focus.column = clamp(app.focus.column+delta, 0, len(columns)-1)
	}
}

func (app *app) activate() {
	switch app.focus.kind {
	case focusTree:
		if app.focus.toggle {
			app.tableMode[pathID(app.focus.path)] = true
			app.expanded[pathID(app.focus.path)] = true
			app.focus = focus{kind: focusTableToggle, path: clonePath(app.focus.path)}
			return
		}
		node, ok := getNode(app.root, app.focus.path)
		if ok && isContainer(node) {
			id := pathID(app.focus.path)
			app.expanded[id] = !app.expanded[id]
		}
	case focusTableToggle:
		delete(app.tableMode, pathID(app.focus.path))
		app.focus = focus{kind: focusTree, path: clonePath(app.focus.path), toggle: true}
	case focusTableCell:
		node, ok := getNode(app.root, app.focus.path)
		if !ok {
			return
		}
		columns := tableColumns(node)
		if app.focus.column < 0 || app.focus.column >= len(columns) {
			return
		}
		value := tableValue(node, app.focus.row, columns[app.focus.column])
		if !isContainer(value) {
			return
		}
		ref := cellRef{
			arrayPath: clonePath(app.focus.path),
			row:       app.focus.row,
			column:    columns[app.focus.column],
		}
		id := cellID(ref)
		if app.expandedCells[id] {
			app.removeCellPrefix(ref)
		} else {
			app.expandedCells[id] = true
		}
	}
}

func (app *app) deepExpand() {
	switch app.focus.kind {
	case focusTree:
		node, ok := getNode(app.root, app.focus.path)
		if ok {
			app.deepExpandTree(node, app.focus.path)
		}
	case focusTableCell:
		node, ok := getNode(app.root, app.focus.path)
		if !ok {
			return
		}
		columns := tableColumns(node)
		if app.focus.column < 0 || app.focus.column >= len(columns) {
			return
		}
		value := tableValue(node, app.focus.row, columns[app.focus.column])
		app.deepExpandCell(value, cellRef{
			arrayPath: clonePath(app.focus.path),
			row:       app.focus.row,
			column:    columns[app.focus.column],
		})
	}
}

func (app *app) deepExpandTree(node any, p path) {
	if !isContainer(node) {
		return
	}
	app.expanded[pathID(p)] = true
	switch v := node.(type) {
	case []any:
		for i, child := range v {
			app.deepExpandTree(child, appendPathIndex(p, i))
		}
	case map[string]any:
		for _, key := range sortedKeys(v) {
			app.deepExpandTree(v[key], appendPathKey(p, key))
		}
	}
}

func (app *app) deepExpandCell(node any, ref cellRef) {
	if !isContainer(node) {
		return
	}
	app.expandedCells[cellID(ref)] = true
	switch v := node.(type) {
	case []any:
		for i, child := range v {
			childRef := ref
			childRef.innerPath = appendPathIndex(ref.innerPath, i)
			app.deepExpandCell(child, childRef)
		}
	case map[string]any:
		for _, key := range sortedKeys(v) {
			childRef := ref
			childRef.innerPath = appendPathKey(ref.innerPath, key)
			app.deepExpandCell(v[key], childRef)
		}
	}
}

func (app *app) deepCollapse() {
	switch app.focus.kind {
	case focusTree:
		parent := pathID(app.focus.path)
		for key := range app.expanded {
			if strings.HasPrefix(key, parent) && key != parent {
				delete(app.expanded, key)
			}
		}
	case focusTableCell:
		node, ok := getNode(app.root, app.focus.path)
		if !ok {
			return
		}
		columns := tableColumns(node)
		if app.focus.column < 0 || app.focus.column >= len(columns) {
			return
		}
		ref := cellRef{
			arrayPath: clonePath(app.focus.path),
			row:       app.focus.row,
			column:    columns[app.focus.column],
		}
		root := cellID(ref)
		for key := range app.expandedCells {
			if strings.HasPrefix(key, root) && key != root {
				delete(app.expandedCells, key)
			}
		}
	}
}

func (app *app) removeCellPrefix(ref cellRef) {
	root := cellID(ref)
	for key := range app.expandedCells {
		if strings.HasPrefix(key, root) {
			delete(app.expandedCells, key)
		}
	}
}

func (app *app) jumpTop(width int) {
	render := app.buildRender(width)
	if len(render.items) == 0 {
		return
	}
	app.focus = focusForItem(render.items[0], app.focus)
}

func (app *app) jumpBottom(width int) {
	render := app.buildRender(width)
	if len(render.items) == 0 {
		return
	}
	last := render.items[len(render.items)-1]
	app.focus = focusForItem(last, app.focus)
	if app.focus.kind == focusTableCell && last.columnCount > 0 {
		app.focus.column = last.columnCount - 1
	}
}

func (app *app) handleClick(term *terminal, x, y int) {
	render := app.buildRender(term.width)
	app.clampFocus(render)
	lineIndex := app.scroll + y - term.startRow
	if y < term.startRow || lineIndex < 0 || lineIndex >= len(render.lines) {
		return
	}
	for _, item := range render.items {
		if lineIndex < item.startLine || lineIndex > item.endLine {
			continue
		}
		switch item.kind {
		case verticalTree:
			newFocus := focus{kind: focusTree, path: clonePath(item.path)}
			if app.focus.kind == focusTree && pathsEqual(app.focus.path, item.path) && app.focus.toggle == newFocus.toggle {
				app.activate()
			} else {
				app.focus = newFocus
			}
		case verticalTableToggle:
			newFocus := focus{kind: focusTableToggle, path: clonePath(item.path)}
			if app.focus.kind == focusTableToggle && pathsEqual(app.focus.path, item.path) {
				app.activate()
			} else {
				app.focus = newFocus
			}
		case verticalTableRow:
			node, ok := getNode(app.root, item.path)
			if !ok {
				return
			}
			columns := tableColumns(node)
			if len(columns) == 0 {
				return
			}
			column := detectTableColumn(columns, x)
			newFocus := focus{kind: focusTableCell, path: clonePath(item.path), row: item.row, column: column}
			if app.focus.kind == focusTableCell && pathsEqual(app.focus.path, item.path) && app.focus.row == item.row && app.focus.column == column {
				app.activate()
			} else {
				app.focus = newFocus
			}
		}
		return
	}
}

func (app *app) clampFocus(render renderOutput) {
	if len(render.items) == 0 {
		return
	}
	for _, item := range render.items {
		switch app.focus.kind {
		case focusTree:
			if item.kind == verticalTree && pathsEqual(item.path, app.focus.path) {
				if app.focus.toggle {
					node, ok := getNode(app.root, app.focus.path)
					if !ok || !isTableCandidate(node) || app.tableMode[pathID(app.focus.path)] {
						app.focus.toggle = false
					}

					}
				}
				return
			}
		case focusTableToggle:
			if item.kind == verticalTableToggle && pathsEqual(item.path, app.focus.path) {
				return
			}
		case focusTableCell:
			if item.kind == verticalTableRow && pathsEqual(item.path, app.focus.path) && item.row == app.focus.row {
				app.focus.column = clamp(app.focus.column, 0, max(0, item.columnCount-1))
				return
			}
		}
	}
	app.focus = focusForItem(render.items[0], app.focus)
}

func (app *app) adjustScroll(render renderOutput, viewportHeight int) {
	if len(render.items) == 0 {
		app.scroll = 0
		return
	}
	line := selectedLineIndex(render, app.focus)
	if line < app.scroll {
		app.scroll = line
	} else if line >= app.scroll+viewportHeight {
		app.scroll = line - viewportHeight + 1
	}
	maxScroll := max(0, len(render.lines)-viewportHeight)
	app.scroll = clamp(app.scroll, 0, maxScroll)
}

func selectedVerticalIndex(render renderOutput, focus focus) int {
	for i, item := range render.items {
		if matchesFocus(item, focus) {
			return i
		}
	}
	return 0
}

func selectedLineIndex(render renderOutput, focus focus) int {
	for _, item := range render.items {
		if matchesFocus(item, focus) {
			return item.startLine
		}
	}
	return 0
}

func matchesFocus(item verticalItem, f focus) bool {
	switch f.kind {
	case focusTree:
		return item.kind == verticalTree && pathsEqual(item.path, f.path)
	case focusTableToggle:
		return item.kind == verticalTableToggle && pathsEqual(item.path, f.path)
	case focusTableCell:
		return item.kind == verticalTableRow && pathsEqual(item.path, f.path) && item.row == f.row
	}
	return false
}

func focusForItem(item verticalItem, current focus) focus {
	switch item.kind {
	case verticalTree:
		return focus{kind: focusTree, path: clonePath(item.path)}
	case verticalTableToggle:
		return focus{kind: focusTableToggle, path: clonePath(item.path)}
	case verticalTableRow:
		col := 0
		if current.kind == focusTableCell {
			col = clamp(current.column, 0, max(0, item.columnCount-1))
		}
		return focus{kind: focusTableCell, path: clonePath(item.path), row: item.row, column: col}
	default:
		return current
	}
}

func linePrefix(depth int, key string, hasKey bool) prefix {
	pfx := prefix{}
	indent := strings.Repeat(" ", depth*2)
	pfx.parts = append(pfx.parts, segment{text: indent})
	pfx.width += stringWidth(indent)
	if hasKey {
		quoted := quoteString(key)
		pfx.parts = append(pfx.parts, segment{text: quoted, face: face{fg: fgKey}})
		pfx.parts = append(pfx.parts, segment{text: ": "})
		pfx.width += stringWidth(quoted) + 2
	}
	return pfx
}

func continuationPrefix(depth int, key string, hasKey bool) prefix {
	pfx := prefix{}
	indent := strings.Repeat(" ", depth*2)
	pfx.parts = append(pfx.parts, segment{text: indent})
	pfx.width += stringWidth(indent)
	if hasKey {
		quoted := quoteString(key)
		spaces := strings.Repeat(" ", stringWidth(quoted))
		pfx.parts = append(pfx.parts, segment{text: spaces, face: face{fg: fgKey}})
		pfx.parts = append(pfx.parts, segment{text: "  "})
		pfx.width += stringWidth(spaces) + 2
	}
	return pfx
}

func pushPrefix(line *styledLine, p prefix) {
	for _, part := range p.parts {
		line.push(part.text, part.face)
	}
}

func (line *styledLine) push(text string, f face) {
	if text == "" {
		return
	}
	line.width += stringWidth(text)
	if len(line.segments) > 0 && line.segments[len(line.segments)-1].face == f {
		line.segments[len(line.segments)-1].text += text
		return
	}
	line.segments = append(line.segments, segment{text: text, face: f})
}

func appendStyledLine(target *styledLine, src styledLine, reverse bool) {
	for _, seg := range src.segments {
		target.push(seg.text, seg.face.withReverse(reverse))
	}
}

func (f face) withReverse(enabled bool) face {
	f.reverse = enabled
	return f
}

func primitiveFace(value any) face {
	switch value.(type) {
	case nil:
		return face{fg: fgNull}
	case bool:
		return face{fg: fgBool}
	case string:
		return face{fg: fgString}
	case json.Number, float64:
		return face{fg: fgNumber}
	default:
		return face{}
	}
}

func serializeValue(value any) string {
	switch v := value.(type) {
	case nil:
		return "null"
	case bool:
		if v {
			return "true"
		}
		return "false"
	case string:
		return quoteString(v)
	case json.Number:
		return v.String()
	case float64:
		return strconv.FormatFloat(v, 'f', -1, 64)
	default:
		data, err := json.Marshal(v)
		if err != nil {
			return "null"
		}
		return string(data)
	}
}

func quoteString(s string) string {
	data, err := json.Marshal(s)
	if err != nil {
		return `""`
	}
	return string(data)
}

func collapsedMarker(node any) string {
	switch node.(type) {
	case []any:
		return "[...]"
	case map[string]any:
		return "{...}"
	default:
		return ""
	}
}

func wrapText(text string, firstWidth, nextWidth int) []string {
	var chunks []string
	remaining := text
	width := max(1, firstWidth)
	for remaining != "" {
		chunk, rest := splitToWidth(remaining, width)
		chunks = append(chunks, chunk)
		remaining = rest
		width = max(1, nextWidth)
	}
	if len(chunks) == 0 {
		chunks = []string{""}
	}
	return chunks
}

func splitToWidth(text string, width int) (string, string) {
	if stringWidth(text) <= width {
		return text, ""
	}
	count := 0
	i := 0
	for idx, r := range text {
		if count+1 > width {
			break
		}
		count++
		i = idx + utf8.RuneLen(r)
	}
	if i == 0 {
		_, size := utf8.DecodeRuneInString(text)
		return text[:size], text[size:]
	}
	return text[:i], text[i:]
}

func clipToWidth(text string, width int) string {
	if width <= 0 {
		return ""
	}
	if stringWidth(text) <= width {
		return text
	}
	count := 0
	i := 0
	for idx, r := range text {
		if count+1 > width {
			break
		}
		count++
		i = idx + utf8.RuneLen(r)
	}
	return text[:i]
}

func stringWidth(text string) int {
	return utf8.RuneCountInString(text)
}

func tableColumns(node any) []string {
	rows, ok := node.([]any)
	if !ok || len(rows) == 0 {
		return nil
	}
	set := map[string]bool{}
	for _, row := range rows {
		obj, ok := row.(map[string]any)
		if !ok {
			return nil
		}
		for key := range obj {
			set[key] = true
		}
	}
	columns := make([]string, 0, len(set))
	for key := range set {
		columns = append(columns, key)
	}
	sort.Strings(columns)
	return columns
}

func tableValue(node any, row int, column string) any {
	rows, ok := node.([]any)
	if !ok || row < 0 || row >= len(rows) {
		return nil
	}
	obj, ok := rows[row].(map[string]any)
	if !ok {
		return nil
	}
	return obj[column]
}

func blockMaxWidth(lines []styledLine) int {
	width := 0
	for _, line := range lines {
		width = max(width, line.width)
	}
	return width
}

func tableBorderLine(indent int, widths []int, left, middle, right string) styledLine {
	var line styledLine
	line.push(strings.Repeat(" ", indent), face{})
	line.push(left, face{})
	for i, width := range widths {
		line.push(strings.Repeat("━", width), face{})
		if i == len(widths)-1 {
			line.push(right, face{})
		} else {
			line.push(middle, face{})
		}
	}
	return line
}

func tableHeaderLine(indent, indexWidth int, columns []string, widths []int) styledLine {
	var line styledLine
	line.push(strings.Repeat(" ", indent), face{})
	line.push(strings.Repeat(" ", indexWidth), face{fg: fgHint})
	line.push("┃", face{})
	for i, name := range columns {
		line.push(name, face{})
		fill := widths[i] - stringWidth(name)

		fill := widths[i] - stringWidth(name)
		if fill > 0 {
			line.push(strings.Repeat(" ", fill), face{})
		}
		line.push("┃", face{})
	}
	return line
}

func detectTableColumn(columns []string, x int) int {
	offset := 0
	for i, col := range columns {
		width := max(5, stringWidth(col))
		if x < offset+width+1 {
			return i
		}
		offset += width + 1
	}
	return max(0, len(columns)-1)
}

func isContainer(node any) bool {
	switch node.(type) {
	case []any, map[string]any:
		return true
	default:
		return false
	}
}

func isObject(node any) bool {
	_, ok := node.(map[string]any)
	return ok
}

func isTableCandidate(node any) bool {
	rows, ok := node.([]any)
	if !ok || len(rows) == 0 {
		return false
	}
	for _, row := range rows {
		if _, ok := row.(map[string]any); !ok {
			return false
		}
	}
	return true
}

func getNode(root any, p path) (any, bool) {
	current := root
	for _, part := range p {
		switch v := current.(type) {
		case []any:
			if part.isKey || part.index < 0 || part.index >= len(v) {
				return nil, false
			}
			current = v[part.index]
		case map[string]any:
			if !part.isKey {
				return nil, false
			}
			child, ok := v[part.key]
			if !ok {
				return nil, false
			}
			current = child
		default:
			return nil, false
		}
	}
	return current, true
}

func sortedKeys(m map[string]any) []string {
	keys := make([]string, 0, len(m))
	for key := range m {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	return keys
}

func pathID(p path) string {
	var b strings.Builder
	for _, part := range p {
		if part.isKey {
			fmt.Fprintf(&b, "k%d:%s/", len(part.key), part.key)
		} else {
			fmt.Fprintf(&b, "i%d/", part.index)
		}
	}
	return b.String()
}

func cellID(ref cellRef) string {
	return pathID(ref.arrayPath) + "#" + strconv.Itoa(ref.row) + "#" + quoteString(ref.column) + "#" + pathID(ref.innerPath)
}

func appendPathIndex(p path, index int) path {
	out := clonePath(p)
	out = append(out, pathPart{index: index})
	return out
}

func appendPathKey(p path, key string) path {
	out := clonePath(p)
	out = append(out, pathPart{isKey: true, key: key})
	return out
}

func clonePath(p path) path {
	out := make(path, len(p))
	copy(out, p)
	return out
}

func pathsEqual(a, b path) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func clamp(value, low, high int) int {
	if value < low {
		return low
	}
	if value > high {
		return high
	}
	return value
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

