func main() {
	code, err := realMain()
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	os.Exit(code)
}

func realMain() (int, error) {
	opts, err := parseOptions(os.Args[1:])
	if err != nil {
		return 1, err
	}

	switch opts.action {
	case actionHelp:
		fmt.Print(helpText)
		return 0, nil
	case actionVersion:
		fmt.Println(version)
		return 0, nil
	case actionKeybinding:
		fmt.Print(keybindingText)
		return 0, nil
	}

	input, err := readInput(opts.file)
	if err != nil {
		return 1, err
	}

	root, err := parseJSON(input)
	if err != nil {
		return 1, err
	}

	app := newApp(root, opts.fullscreen)
	term, err := newTerminal(opts.fullscreen)
	if err != nil {
		return 1, err
	}
	defer term.leave()

	for {
		if err := term.render(app); err != nil {
			return 1, err
		}
		ev, err := term.nextEvent()
		if err != nil {
			return 1, err
		}
		if handleEvent(app, term, ev) {
			return 0, nil
		}
	}
}

